SELECT 439 f,profile,CASE WHEN p IS NULL THEN 'null' WHEN p>=19509 THEN 'after' WHEN p>=19478 THEN 'in' WHEN p=19477 THEN 'b001' WHEN p>19448 THEN 'b002' ELSE 'b030' END pb,d,CASE WHEN sn>=2 THEN 2 ELSE sn END sn,se,sd,ss,count(*) n FROM (SELECT n.profile profile,(n.published_at+ifnull(n.published_offset,0)*60)/86400 p,n.dispatched_at IS NOT NULL d,(SELECT count(*) FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id) sn,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id AND +o.fetch_id>439 AND +o.fetch_id<=444) se,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id AND +o.published_at=n.published_at) sd,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id=n.publication_id AND o.id<>n.id) ss FROM notices n WHERE n.fetch_id=439) GROUP BY profile,pb,d,CASE WHEN sn>=2 THEN 2 ELSE sn END,se,sd,ss
UNION ALL
SELECT 491 f,profile,CASE WHEN p IS NULL THEN 'null' WHEN p>=20679 THEN 'after' WHEN p>=20678 THEN 'in' WHEN p=20677 THEN 'b001' WHEN p>20648 THEN 'b002' ELSE 'b030' END pb,d,CASE WHEN sn>=2 THEN 2 ELSE sn END sn,se,sd,ss,count(*) n FROM (SELECT n.profile profile,(n.published_at+ifnull(n.published_offset,0)*60)/86400 p,n.dispatched_at IS NOT NULL d,(SELECT count(*) FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id) sn,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id AND +o.fetch_id<491) se,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id>=substr(n.publication_id,1,36)||'-' AND o.publication_id<substr(n.publication_id,1,36)||'.' AND o.id<>n.id AND +o.published_at=n.published_at) sd,EXISTS(SELECT 1 FROM notices o WHERE o.source='doe' AND o.publication_id=n.publication_id AND o.id<>n.id) ss FROM notices n WHERE n.fetch_id=491) GROUP BY profile,pb,d,CASE WHEN sn>=2 THEN 2 ELSE sn END,se,sd,ss
